  async function send(event: FormEvent) { event.preventDefault(); if (!conversation) return; await action(async () => { const next = await api<ChatDetail>("/api/workspace/chat/" + conversation.id + "/messages", "POST", { requestId: crypto.randomUUID(), revision: conversation.revision, text, task, useGemini, query }); setDetail(next); setText(""); setNotice("Message and response saved. No business change was authorized."); composer.current?.focus(); await reloadList(); }); }
