  function editProposal(p: ProposalDTO) { const op = p.operation; setKind(op.kind); if (op.kind === "PROFILE_EDIT") { setTarget(op.targetId === conversation?.sourceId ? "SOURCE" : "CANDIDATE"); setField(op.field); setValue(op.after ?? ""); } else if (op.kind === "WORKFLOW_NAVIGATE") setStep(op.step); else if (op.kind === "DRAFT_CREATE") setRecipient(op.recipient); else { setSubject(op.subject); setBody(op.body); } setReviseId(p.id); setNotice("Editing proposal values. Saving creates a new revision and requires fresh review."); }
